  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    # Build map from parent id to list of child ids
    children = {}
    for n in nodes:
        pid = n.get('parent')
        if pid is not None:
            children.setdefault(pid, []).append(n['id'])
    # All node ids initially retained
    retained = set(n['id'] for n in nodes)
    removed = []
    # Sort by depth descending, then by id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    for n in sorted_nodes:
        nid = n['id']
        if nid not in retained:
            continue
        # Never remove the root (parent is None)
        if n['parent'] is None:
            continue
        # Never remove a node with a required symbol
        if n['symbol'] in required_symbols:
            continue
        # Never remove a node that still has any child in the retained set
        child_ids = children.get(nid, [])
        if any(cid in retained for cid in child_ids):
            continue
        # Tentatively remove: check that all required symbols remain after removal
        remaining_symbols = set()
        for rid in retained:
            if rid != nid:
                remaining_symbols.add(node_map[rid]['symbol'])
        if required_symbols.issubset(remaining_symbols):
            retained.remove(nid)
            removed.append(nid)
    # Sort retained ids alphabetically
    retained_sorted = sorted(retained)
    return {"removed_node_ids": removed, "retained_node_ids": retained_sorted}"
}
